import subprocess
import psutil

def task_func(process_name: str) -> str:
    """
    Check if a process with the given name is running.
    If it is, terminate all such processes, start a new one,
    and return 'Process found. Restarting <process_name>.'.
    If it is not running, start it and return
    'Process not found. Starting <process_name>.'.
    """
    # Find all running processes with the specified name
    running_procs = []
    for proc in psutil.process_iter(['name']):
        try:
            if proc.info['name'] == process_name:
                running_procs.append(proc)
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            continue

    if running_procs:
        # Terminate all found processes
        for proc in running_procs:
            try:
                proc.terminate()
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                continue
        # Wait for termination to complete
        for proc in running_procs:
            try:
                proc.wait(timeout=5)
            except (psutil.NoSuchProcess, psutil.TimeoutExpired):
                # If it didn't terminate gracefully, force kill
                try:
                    proc.kill()
                except (psutil.NoSuchProcess, psutil.AccessDenied):
                    pass

        # Start a new instance of the process
        try:
            subprocess.Popen(process_name, shell=True)
        except Exception:
            # If starting fails, we still return the restart message
            pass

        return f'Process found. Restarting {process_name}.'

    # No running instance found – start it
    try:
        subprocess.Popen(process_name, shell=True)
    except Exception:
        pass

    return f'Process not found. Starting {process_name}.'

