import urllib.request
import os
import hashlib
import tarfile

# Constants
TARGET_TAR_FILE = "downloaded_files.tar.gz"
EXPECTED_MD5_CHECKSUM = "d41d8cd98f00b204e9800998ecf8427e"

def task_func(url):
    """
    Download a file from the given URL and save it as TARGET_TAR_FILE.
    Compute its MD5 checksum and compare it with EXPECTED_MD5_CHECKSUM.
    If the checksum does not match, delete the downloaded file and return False.
    Return True if the download succeeds and the checksum matches.
    """
    # Remove any existing file with the same name
    if os.path.exists(TARGET_TAR_FILE):
        try:
            os.remove(TARGET_TAR_FILE)
        except Exception:
            return False

    # Attempt to download the file
    try:
        urllib.request.urlretrieve(url, TARGET_TAR_FILE)
    except Exception:
        return False

    # Verify that the file exists
    if not os.path.isfile(TARGET_TAR_FILE):
        return False

    # Compute MD5 checksum of the downloaded file
    try:
        md5 = hashlib.md5()
        with open(TARGET_TAR_FILE, "rb") as f:
            for chunk in iter(lambda: f.read(8192), b""):
                md5.update(chunk)
        file_md5 = md5.hexdigest()
    except Exception:
        # If we can't read the file, treat it as a failure
        try:
            os.remove(TARGET_TAR_FILE)
        except Exception:
            pass
        return False

    # Compare checksums
    if file_md5 != EXPECTED_MD5_CHECKSUM:
        # Delete the file if checksum does not match
        try:
            os.remove(TARGET_TAR_FILE)
        except Exception:
            pass
        return False

    # Optional: ensure the file is a valid tar.gz archive
    if not tarfile.is_tarfile(TARGET_TAR_FILE):
        try:
            os.remove(TARGET_TAR_FILE)
        except Exception:
            pass
        return False

    return True

