import json
import requests
import chardet

# Constants
API_URL = "http://api.example.com/data"

def task_func(url=API_URL, to_encoding="utf8"):
    """
    Fetch data from the specified REST API URL using an HTTP GET request with a 5‑second timeout.
    The response content is retrieved as bytes. If the content is empty, an empty dictionary is returned.
    Otherwise, the bytes are decoded (using chardet to detect the encoding, falling back to `to_encoding`)
    and parsed as JSON. If parsing fails, an empty dictionary is returned.

    Parameters
    ----------
    url : str, optional
        The API endpoint to query. Defaults to API_URL.
    to_encoding : str, optional
        Fallback encoding to use if chardet cannot detect the encoding. Defaults to "utf8".

    Returns
    -------
    dict
        The parsed JSON data, or an empty dictionary if the response is empty or invalid.
    """
    try:
        response = requests.get(url, timeout=5)
        content_bytes = response.content
    except requests.exceptions.RequestException:
        # Network error or timeout
        return {}

    if not content_bytes:
        # Empty response
        return {}

    # Detect encoding
    detection = chardet.detect(content_bytes)
    encoding = detection.get("encoding") or to_encoding

    try:
        decoded_text = content_bytes.decode(encoding, errors="replace")
    except (LookupError, UnicodeDecodeError):
        # Fallback to the provided encoding if decoding fails
        try:
            decoded_text = content_bytes.decode(to_encoding, errors="replace")
        except Exception:
            return {}

    try:
        data = json.loads(decoded_text)
        if isinstance(data, dict):
            return data
        # If the JSON is not a dict, wrap it in a dict
        return {"data": data}
    except json.JSONDecodeError:
        # Invalid JSON
        return {}

