from flask_wtf import FlaskForm
from wtforms import StringField, PasswordField, SubmitField
from wtforms.validators import DataRequired
from flask_login import (
    LoginManager,
    login_user,
    login_required,
    logout_user,
    current_user,
    UserMixin,
)
from werkzeug.security import generate_password_hash, check_password_hash


def create_app(secret_key: str, template_folder: str) -> Flask:
    """
    Create and configure a Flask application.

    Parameters
    ----------
    secret_key : str
        Secret key used for session signing and CSRF protection.
    template_folder : str
        Path to the folder containing template files.

    Returns
    -------
    Flask
        The configured Flask application instance.
    """
    app = Flask(__name__, template_folder=template_folder)
    app.config["SECRET_KEY"] = secret_key

    # ---------- Flask‑Login setup ----------
    login_manager = LoginManager()
    login_manager.init_app(app)
    login_manager.login_view = "login"

    # ---------- In‑memory user store ----------
    users = {
        "alice": generate_password_hash("alicepass"),
        "bob": generate_password_hash("bobpass"),
    }

    class User(UserMixin):
        def __init__(self, username: str):
            self.id = username

    @login_manager.user_loader
    def load_user(user_id: str):
        if user_id in users:
            return User(user_id)
        return None

    # ---------- Login form ----------
    class LoginForm(FlaskForm):
        username = StringField("Username", validators=[DataRequired()])
        password = PasswordField("Password", validators=[DataRequired()])
        submit = SubmitField("Login")

    # ---------- Templates ----------
    login_template = """
    <!doctype html>
    <title>Login</title>
    <h1>Login</h1>
    <form method="post">
        {{ form.hidden_tag() }}
        <p>
            {{ form.username.label }}<br>
            {{ form.username(size=32) }}
        </p>
        <p>
            {{ form.password.label }}<br>
            {{ form.password(size=32) }}
        </p>
        <p>{{ form.submit() }}</p>
    </form>
    {% if error %}
    <p style="color:red;">{{ error }}</p>
    {% endif %}
    """

    welcome_template = """
    <!doctype html>
    <title>Welcome</title>
    <h1>Hello, {{ current_user.id }}!</h1>
    <p><a href="{{ url_for('logout') }}">Logout</a></p>
    <p><a href="{{ url_for('protected') }}">Protected Page</a></p>
    """

    protected_template = """
    <!doctype html>
    <title>Protected</title>
    <h1>Logged in as: {{ current_user.id }}</h1>
    <p><a href="{{ url_for('logout') }}">Logout</a></p>
    """

    # ---------- Routes ----------
    @app.route("/login", methods=["GET", "POST"])
    def login():
        form = LoginForm()
        error = None
        if form.validate_on_submit():
            username = form.username.data
            password = form.password.data
            if username in users and check_password_hash(users[username], password):
                user = User(username)
                login_user(user)
                return redirect(url_for("welcome"))
