import cgi
import http.server
import json

SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}

def task_func():
    class SimplePostHandler(http.server.BaseHTTPRequestHandler):
        def do_POST(self):
            # Read the request body
            content_length = int(self.headers.get('Content-Length', 0))
            body = self.rfile.read(content_length)

            # Attempt to parse JSON; ignore errors
            try:
                payload = json.loads(body)
            except Exception:
                payload = {}

            # Check for 'data' key
            if isinstance(payload, dict) and 'data' in payload:
                self.send_response(200)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                self.wfile.write(json.dumps(SUCCESS_RESPONSE).encode('utf-8'))
            else:
                # Respond with 400 if 'data' key is missing
                self.send_response(400)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                error_resp = {
                    'status': 'error',
                    'message': 'Missing data key.'
                }
                self.wfile.write(json.dumps(error_resp).encode('utf-8'))

        # Suppress logging to keep output clean
        def log_message(self, format, *args):
            return

    # Start the HTTP server on localhost:8000
    server_address = ('', 8000)
    httpd = http.server.HTTPServer(server_address, SimplePostHandler)
    print("Serving on port 8000...")
    httpd.serve_forever()

